% --- Abstract -------------------------------------------------------------
\begin{abstract}
We formalize in \Lean/\Mathlib an exterior-model spinor package for split
quadratic spaces over fields $K$ with $2\in K^\times$. The development keeps the
chosen hyperbolic or split-Witt presentation as data, so the spinor module
$\bigwedge W$, its chiral halves, and the transported Clifford and spin actions
remain available throughout the covering-map arguments. This explicit
chosen-model interface lets the paper state field-sensitive image theorems at
the theorem level. In positive split rank the kernel of
$\Spin(V,Q)\to\SO(V,Q)$ is $\{\pm1\}$, and the exterior-model spin action
therefore descends only projectively to the orthogonal image. For a split line,
the spin image is exactly the square-scaling subgroup. In finite split rank with
a distinguished line, a split Levi element lies in the spin image exactly when
its determinant is a square in $K^\times$; equivalently, the determinant
square-class character has the spin image as kernel and gives quotient
isomorphisms to $K^\times/(K^\times)^2$. The formalization also packages
explicit Clifford-unit representatives for transvections and chosen-line square
scalings, their torus law, algebraically closed specializations, and a
Clifford-level vector-product norm substrate with order and repetition
invariance.
\end{abstract}

\maketitle

% --- 1. Introduction -----------------------------------------------------

\section{Context}
\label{sec:related}

\paragraph{Mathematical background.} Our treatment follows the classical
presentations of Lawson--Michelsohn~\cite{LawsonMichelsohn1989},
Chevalley~\cite{Chevalley1996}, Atiyah--Bott--Shapiro~\cite{AtiyahBottShapiro1964},
and Lounesto~\cite{Lounesto2001}, with the low-dimensional octonionic and
quaternionic incidences drawn from Baez~\cite{Baez2002}. The underlying
``choose a maximal isotropic and use $\bigwedge W$'' construction is classical;
the point here is to keep the choice data explicit and stable under transport.

